import { useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, PieChart, Pie, Cell, Legend 
} from 'recharts';
import { 
  TrendingUp, Users, Package, DollarSign, 
  ArrowUpRight, AlertTriangle, Coffee 
} from 'lucide-react';
import api from '../../api/axios';
import Swal from 'sweetalert2';

const COLORS = ['#2C1810', '#C8860A', '#6B3A23', '#D4A77A', '#1D6830'];

export default function ReportesPage() {
  const [stats, setStats] = useState(null);
  const [tendencia, setTendencia] = useState([]);
  const [categorias, setCategorias] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [resStats, resTendencia, resCats] = await Promise.all([
          api.get('/reportes/dashboard'),
          api.get('/reportes/tendencia'),
          api.get('/reportes/categorias')
        ]);

        setStats(resStats.data.data);
        setTendencia(resTendencia.data.data);
        setCategorias(resCats.data.data);
      } catch (error) {
        Swal.fire('Error', 'No se pudieron cargar los reportes', 'error');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <div className="loading-wrap">
        <div className="spinner"></div>
        <span>Cargando análisis...</span>
      </div>
    );
  }

  return (
    <div className="animate-in">
      <header className="page-header">
        <div className="page-title">
          <h1>Reportes y Análisis</h1>
          <p className="text-muted">Desempeño del POS — Cafecito Feliz</p>
        </div>
        <div className="flex gap-2">
          <button className="btn btn-outline btn-sm" onClick={() => window.print()}>
            Exportar PDF
          </button>
        </div>
      </header>

      {/* Grid de KPIs */}
      <section className="stats-grid">
        <div className="stat-card">
          <div className="stat-card__icon success">
            <DollarSign size={24} />
          </div>
          <div className="stat-card__content">
            <span className="stat-card__label">Ventas Hoy</span>
            <span className="stat-card__value">${stats.hoy.total.toLocaleString()}</span>
            <span className="text-small text-muted flex items-center gap-1">
              <ArrowUpRight size={14} className="text-success" />
              {stats.hoy.count} tickets emitidos
            </span>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-card__icon primary">
            <TrendingUp size={24} />
          </div>
          <div className="stat-card__content">
            <span className="stat-card__label">Ventas Históricas</span>
            <span className="stat-card__value">${stats.historico.total.toLocaleString()}</span>
            <span className="text-small text-muted">
              {stats.historico.count} ventas realizadas
            </span>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-card__icon info">
            <Package size={24} />
          </div>
          <div className="stat-card__content">
            <span className="stat-card__label">Resumen Inventario</span>
            <span className="stat-card__value">Ok</span>
            <span className="text-small text-muted">
              Estado operativo normal
            </span>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-card__icon danger">
            <AlertTriangle size={24} />
          </div>
          <div className="stat-card__content">
            <span className="stat-card__label">Alertas Stock</span>
            <span className="stat-card__value">{stats.stockBajoAlertas}</span>
            <span className="text-small text-muted">Productos por agotarse</span>
          </div>
        </div>
      </section>

      {/* Gráficas Principales */}
      <div className="reports-grid">
        {/* Tendencia Semanal */}
        <div className="chart-container">
          <div className="chart-header">
            <h3>Tendencia de Ventas (Últimos 7 días)</h3>
          </div>
          <div style={{ width: '100%', height: 350 }}>
            <ResponsiveContainer>
              <AreaChart data={tendencia}>
                <defs>
                  <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#C8860A" stopOpacity={0.15}/>
                    <stop offset="95%" stopColor="#C8860A" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F0E4D7" />
                <XAxis 
                  dataKey="_id" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 12, fill: '#7A5C45' }}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 12, fill: '#7A5C45' }}
                />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 16px rgba(0,0,0,0.1)' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="total" 
                  stroke="#C8860A" 
                  strokeWidth={3}
                  fillOpacity={1} 
                  fill="url(#colorTotal)" 
                  name="Ventas ($)"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Categorías */}
        <div className="chart-container">
          <div className="chart-header">
            <h3>Ventas por Categoría</h3>
          </div>
          <div style={{ width: '100%', height: 350 }}>
            <ResponsiveContainer>
              <PieChart>
                <Pie
                  data={categorias}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="total"
                  nameKey="_id"
                >
                  {categorias.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="reports-grid mt-4">
        {/* Top Productos */}
        <div className="chart-container">
          <div className="chart-header">
            <h3>Ranking: Top 5 Productos</h3>
          </div>
          <div className="top-products-list">
            {stats.topProductos.map((prod, idx) => (
              <div key={prod._id} className="product-rank-item">
                <div className="rank-number">{idx + 1}</div>
                <div className="flex-1">
                  <h4 className="mb-1">{prod.nombre}</h4>
                  <div className="flex justify-between items-center">
                    <span className="text-small text-muted">{prod.vendidos} unidades vendidas</span>
                    <span className="font-bold text-success">${prod.ingresos.toLocaleString()}</span>
                  </div>
                  <div className="w-full bg-mist mt-1" style={{ height: '4px', borderRadius: '2px' }}>
                    <div 
                      className="bg-caramel" 
                      style={{ 
                        height: '100%', 
                        borderRadius: '2px',
                        width: `${(prod.vendidos / stats.topProductos[0].vendidos) * 100}%` 
                      }}
                    ></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Info Card */}
        <div className="card" style={{ background: 'var(--c-espresso)', color: 'white' }}>
          <div className="card-body flex flex-col items-center justify-center text-center gap-4" style={{ height: '100%' }}>
            <div style={{ background: 'rgba(255,255,255,0.1)', padding: '1.5rem', borderRadius: '50%' }}>
              <Coffee size={48} className="text-caramel-lt" />
            </div>
            <div>
              <h3 className="mb-2">Resumen Operativo</h3>
              <p style={{ opacity: 0.8, fontSize: '0.9rem' }}>
                Tu tienda ha tenido un rendimiento estable. 
                Los productos de categoría <b>{categorias[0]?._id}</b> son tus mejores aliados este mes.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
